SET NAMES utf8mb4; SET FOREIGN_KEY_CHECKS=0;
CREATE TABLE users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('user','admin') NOT NULL DEFAULT 'user',status ENUM('active','suspended') NOT NULL DEFAULT 'active',access_status ENUM('free','pending_payment','full','expired','revoked') NOT NULL DEFAULT 'free',email_verified_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,deleted_at DATETIME NULL,INDEX(role,status));
CREATE TABLE password_reset_tokens(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,token_hash CHAR(64) NOT NULL UNIQUE,expires_at DATETIME NOT NULL,used_at DATETIME NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id)REFERENCES users(id)ON DELETE CASCADE);
CREATE TABLE email_verification_tokens(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,token_hash CHAR(64) NOT NULL UNIQUE,expires_at DATETIME NOT NULL,used_at DATETIME NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id)REFERENCES users(id)ON DELETE CASCADE);
CREATE TABLE specialties(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,slug VARCHAR(160) NOT NULL UNIQUE,description VARCHAR(255) NOT NULL,icon VARCHAR(60) NOT NULL,color CHAR(7) NOT NULL,is_active BOOLEAN NOT NULL DEFAULT TRUE,display_order SMALLINT NOT NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,deleted_at DATETIME NULL,INDEX(is_active,display_order));
CREATE TABLE topics(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,specialty_id INT UNSIGNED NOT NULL,name VARCHAR(160) NOT NULL,slug VARCHAR(170) NOT NULL,difficulty ENUM('easy','medium','hard','mixed') DEFAULT 'mixed',is_active BOOLEAN DEFAULT TRUE,display_order SMALLINT DEFAULT 0,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,deleted_at DATETIME NULL,UNIQUE(specialty_id,slug),FOREIGN KEY(specialty_id)REFERENCES specialties(id));
CREATE TABLE questions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,specialty_id INT UNSIGNED NOT NULL,topic_id INT UNSIGNED NOT NULL,vignette TEXT NOT NULL,stem TEXT NOT NULL,explanation TEXT NOT NULL,learning_objective TEXT NULL,pearl TEXT NULL,difficulty ENUM('easy','medium','hard') NOT NULL,status ENUM('draft','review','published','archived') DEFAULT 'draft',creator_id BIGINT UNSIGNED NULL,reviewer_id BIGINT UNSIGNED NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,deleted_at DATETIME NULL,FOREIGN KEY(specialty_id)REFERENCES specialties(id),FOREIGN KEY(topic_id)REFERENCES topics(id),FOREIGN KEY(creator_id)REFERENCES users(id),FOREIGN KEY(reviewer_id)REFERENCES users(id),INDEX(status,specialty_id,topic_id,difficulty));
CREATE TABLE question_options(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,question_id BIGINT UNSIGNED NOT NULL,label CHAR(1) NOT NULL,option_text TEXT NOT NULL,is_correct BOOLEAN NOT NULL DEFAULT FALSE,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE(question_id,label),FOREIGN KEY(question_id)REFERENCES questions(id)ON DELETE CASCADE);
CREATE TABLE question_references(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,question_id BIGINT UNSIGNED NOT NULL,title VARCHAR(255) NOT NULL,authors VARCHAR(255),publication_year SMALLINT,url VARCHAR(500),doi VARCHAR(150),created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(question_id)REFERENCES questions(id)ON DELETE CASCADE);
CREATE TABLE tags(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(80) UNIQUE,slug VARCHAR(90) UNIQUE,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE question_tags(question_id BIGINT UNSIGNED,tag_id INT UNSIGNED,PRIMARY KEY(question_id,tag_id),FOREIGN KEY(question_id)REFERENCES questions(id)ON DELETE CASCADE,FOREIGN KEY(tag_id)REFERENCES tags(id)ON DELETE CASCADE);
CREATE TABLE quiz_attempts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,specialty_id INT UNSIGNED NULL,topic_id INT UNSIGNED NULL,mode ENUM('demo','practice','topic','incorrect','bookmark','tryout') NOT NULL,status ENUM('in_progress','submitted','expired') DEFAULT 'in_progress',total_questions SMALLINT NOT NULL,duration_minutes SMALLINT NOT NULL,correct_count SMALLINT DEFAULT 0,incorrect_count SMALLINT DEFAULT 0,score DECIMAL(5,2) NULL,duration_seconds INT DEFAULT 0,started_at DATETIME,submitted_at DATETIME NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id)REFERENCES users(id),FOREIGN KEY(specialty_id)REFERENCES specialties(id),FOREIGN KEY(topic_id)REFERENCES topics(id),INDEX(user_id,status,created_at));
CREATE TABLE quiz_attempt_questions(attempt_id BIGINT UNSIGNED,question_id BIGINT UNSIGNED,position SMALLINT NOT NULL,marked_review BOOLEAN DEFAULT FALSE,PRIMARY KEY(attempt_id,question_id),UNIQUE(attempt_id,position),FOREIGN KEY(attempt_id)REFERENCES quiz_attempts(id)ON DELETE CASCADE,FOREIGN KEY(question_id)REFERENCES questions(id));
CREATE TABLE quiz_answers(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,attempt_id BIGINT UNSIGNED NOT NULL,question_id BIGINT UNSIGNED NOT NULL,option_id BIGINT UNSIGNED NOT NULL,answered_at DATETIME,UNIQUE(attempt_id,question_id),FOREIGN KEY(attempt_id)REFERENCES quiz_attempts(id)ON DELETE CASCADE,FOREIGN KEY(question_id)REFERENCES questions(id),FOREIGN KEY(option_id)REFERENCES question_options(id));
CREATE TABLE bookmarks(user_id BIGINT UNSIGNED,question_id BIGINT UNSIGNED,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,question_id),FOREIGN KEY(user_id)REFERENCES users(id)ON DELETE CASCADE,FOREIGN KEY(question_id)REFERENCES questions(id)ON DELETE CASCADE);
CREATE TABLE payments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,sender_name VARCHAR(120) NOT NULL,bank VARCHAR(80) NOT NULL,transfer_date DATE NOT NULL,amount DECIMAL(12,2) NOT NULL,proof_path VARCHAR(120) NOT NULL,status ENUM('pending','approved','rejected') DEFAULT 'pending',rejection_reason TEXT NULL,admin_note TEXT NULL,reviewed_by BIGINT UNSIGNED NULL,reviewed_at DATETIME NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id)REFERENCES users(id),FOREIGN KEY(reviewed_by)REFERENCES users(id),INDEX(status,created_at));
CREATE TABLE notifications(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,title VARCHAR(160),message TEXT,is_read BOOLEAN DEFAULT FALSE,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id)REFERENCES users(id)ON DELETE CASCADE,INDEX(user_id,is_read));
CREATE TABLE settings(setting_key VARCHAR(100) PRIMARY KEY,setting_value TEXT NOT NULL,is_public BOOLEAN DEFAULT FALSE,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE audit_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,action VARCHAR(100) NOT NULL,entity_type VARCHAR(80),entity_id BIGINT UNSIGNED,old_values JSON,new_values JSON,ip_address VARCHAR(45),created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id)REFERENCES users(id),INDEX(entity_type,entity_id),INDEX(created_at));
CREATE TABLE login_attempts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(190),ip_address VARCHAR(45) NOT NULL,successful BOOLEAN NOT NULL,attempted_at DATETIME DEFAULT CURRENT_TIMESTAMP,INDEX(ip_address,attempted_at),INDEX(email,attempted_at));
SET FOREIGN_KEY_CHECKS=1;

-- Scalable question-bank taxonomy and editorial workflow (no synthetic medical content).
CREATE TABLE competencies(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,specialty_id INT UNSIGNED NOT NULL,name VARCHAR(160) NOT NULL,weight DECIMAL(5,2) NOT NULL DEFAULT 0,display_order SMALLINT DEFAULT 0,FOREIGN KEY(specialty_id) REFERENCES specialties(id),INDEX(specialty_id));
CREATE TABLE subtopics(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,topic_id INT UNSIGNED NOT NULL,name VARCHAR(160) NOT NULL,slug VARCHAR(170) NOT NULL,is_active BOOLEAN DEFAULT TRUE,UNIQUE(topic_id,slug),FOREIGN KEY(topic_id) REFERENCES topics(id),INDEX(topic_id,is_active));
ALTER TABLE questions ADD competency_id INT UNSIGNED NULL, ADD subtopic_id INT UNSIGNED NULL, ADD question_type ENUM('single_best_answer','multiple_choice','clinical_vignette','laboratory','radiology','ekg','image_based','matching','true_false','sequential_case','guideline','emergency_case') NOT NULL DEFAULT 'single_best_answer', ADD reference_year SMALLINT NULL, ADD review_date DATETIME NULL, ADD version_no INT UNSIGNED NOT NULL DEFAULT 1, ADD published_at DATETIME NULL, MODIFY status ENUM('draft','in_review','revision_required','approved','published','archived') DEFAULT 'draft', ADD FULLTEXT INDEX ft_question(vignette,stem), ADD INDEX idx_question_filters(specialty_id,topic_id,difficulty,status,question_type,published_at), ADD FOREIGN KEY(competency_id) REFERENCES competencies(id), ADD FOREIGN KEY(subtopic_id) REFERENCES subtopics(id);
CREATE TABLE question_explanations(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,question_id BIGINT UNSIGNED NOT NULL UNIQUE,main_concept TEXT NOT NULL,clinical_reasoning TEXT NOT NULL,correct_reason TEXT NOT NULL,incorrect_reasons JSON NOT NULL,clinical_pearl TEXT NULL,red_flag TEXT NULL,relearn_material TEXT NULL,FOREIGN KEY(question_id) REFERENCES questions(id) ON DELETE CASCADE);
CREATE TABLE question_versions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,question_id BIGINT UNSIGNED NOT NULL,version_no INT UNSIGNED NOT NULL,snapshot JSON NOT NULL,change_summary VARCHAR(500),created_by BIGINT UNSIGNED,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,UNIQUE(question_id,version_no),FOREIGN KEY(question_id) REFERENCES questions(id),FOREIGN KEY(created_by) REFERENCES users(id));
CREATE TABLE personal_notes(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,question_id BIGINT UNSIGNED NOT NULL,note TEXT NOT NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE(user_id,question_id),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(question_id) REFERENCES questions(id));
CREATE TABLE question_reports(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,question_id BIGINT UNSIGNED NOT NULL,reason VARCHAR(100) NOT NULL,detail TEXT,status ENUM('open','investigating','resolved','dismissed') DEFAULT 'open',created_at DATETIME DEFAULT CURRENT_TIMESTAMP,INDEX(status,created_at),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(question_id) REFERENCES questions(id));
CREATE TABLE tryouts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(180) NOT NULL,specialty_id INT UNSIGNED,kind ENUM('scheduled','self_paced') NOT NULL,starts_at DATETIME,ends_at DATETIME,duration_minutes SMALLINT NOT NULL,status ENUM('draft','published','closed') DEFAULT 'draft',FOREIGN KEY(specialty_id) REFERENCES specialties(id));
CREATE TABLE tryout_blueprints(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tryout_id BIGINT UNSIGNED NOT NULL,topic_id INT UNSIGNED,difficulty ENUM('easy','medium','hard'),question_count SMALLINT NOT NULL,weight DECIMAL(5,2),FOREIGN KEY(tryout_id) REFERENCES tryouts(id),FOREIGN KEY(topic_id) REFERENCES topics(id));
CREATE TABLE daily_quizzes(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,specialty_id INT UNSIGNED NOT NULL,quiz_date DATE NOT NULL,attempt_id BIGINT UNSIGNED,status ENUM('pending','in_progress','completed') DEFAULT 'pending',UNIQUE(user_id,quiz_date),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(specialty_id) REFERENCES specialties(id),FOREIGN KEY(attempt_id) REFERENCES quiz_attempts(id));
CREATE TABLE user_mastery(user_id BIGINT UNSIGNED NOT NULL,topic_id INT UNSIGNED NOT NULL,mastery DECIMAL(5,2) DEFAULT 0,attempt_count INT UNSIGNED DEFAULT 0,last_attempt_at DATETIME,PRIMARY KEY(user_id,topic_id),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(topic_id) REFERENCES topics(id));
CREATE TABLE review_schedules(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,question_id BIGINT UNSIGNED NOT NULL,next_review_at DATETIME NOT NULL,interval_days SMALLINT DEFAULT 1,ease_factor DECIMAL(4,2) DEFAULT 2.50,INDEX(user_id,next_review_at),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(question_id) REFERENCES questions(id));
CREATE TABLE content_reviews(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,question_id BIGINT UNSIGNED NOT NULL,reviewer_id BIGINT UNSIGNED NOT NULL,status ENUM('in_review','revision_required','approved') NOT NULL,notes TEXT,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,INDEX(question_id,status),FOREIGN KEY(question_id) REFERENCES questions(id),FOREIGN KEY(reviewer_id) REFERENCES users(id));
